    Português: "Use o menu de três pontos para ocultar o cartão, editar títulos, exportar ou mudar a cor.",
    "Русский (Russian)": "Используйте меню с тремя точками, чтобы скрыть карту, изменить заголовки, экспортировать или сменить цвет.",
