  "Upload a photo or scan — NivaDesk reads the total and date and finds the transaction.": { "Türkçe": "Fotoğraf veya tarama yükle — NivaDesk tutarı ve tarihi okuyup işlemi bulur.", "Deutsch": "Foto oder Scan hochladen — NivaDesk liest Betrag und Datum und findet die Transaktion.", "Français": "Importez une photo ou un scan — NivaDesk lit le total et la date et trouve la transaction.", "Italiano": "Carica una foto o scansione — NivaDesk legge totale e data e trova la transazione.", "Español (Spanish)": "Sube una foto o escaneo — NivaDesk lee el total y la fecha y encuentra la transacción.", "Português": "Carregue uma foto ou digitalização — o NivaDesk lê o total e a data e encontra a transação.", "Русский (Russian)": "Загрузите фото или скан — NivaDesk прочитает сумму и дату и найдёт операцию.", "日本語 (Japanese)": "写真やスキャンをアップロード — NivaDeskが合計と日付を読み取り取引を見つけます。", "中文 (Chinese)": "上传照片或扫描件 — NivaDesk 读取金额和日期并找到交易。", "العربية (Arabic)": "ارفع صورة أو مسحًا — يقرأ NivaDesk المجموع والتاريخ ويجد المعاملة.", "हिन्दी (Hindi)": "फ़ोटो या स्कैन अपलोड करें — NivaDesk कुल और तारीख पढ़कर लेन-देन ढूँढता है।" },
