  "Click a rule to preview what it matches.": { "Türkçe": "Neyle eşleştiğini görmek için bir kurala tıklayın.", "Deutsch": "Klicken Sie auf eine Regel, um die Treffer zu sehen.", "Français": "Cliquez sur une règle pour voir ses correspondances.", "Italiano": "Clicca una regola per vedere cosa corrisponde.", "Español (Spanish)": "Haz clic en una regla para ver sus coincidencias.", "Português": "Clique numa regra para ver o que corresponde.", "Русский (Russian)": "Нажмите на правило, чтобы увидеть совпадения.", "日本語 (Japanese)": "ルールをクリックすると一致内容を確認できます。", "中文 (Chinese)": "点击规则以预览匹配项。", "العربية (Arabic)": "انقر على قاعدة لمعاينة ما تطابقه.", "हिन्दी (Hindi)": "मिलान देखने के लिए नियम पर क्लिक करें।" },
