  "Still no payment — check the amount or assign it by hand": { "Türkçe": "Hâlâ ödeme yok — tutarı kontrol et ya da elle ata", "Deutsch": "Noch keine Zahlung — Betrag prüfen oder manuell zuordnen", "Français": "Toujours aucun paiement — vérifiez le montant ou affectez-le manuellement", "Italiano": "Ancora nessun pagamento — controlla l'importo o assegna manualmente", "Español (Spanish)": "Aún sin pago — revisa el importe o asígnalo a mano", "Português": "Ainda sem pagamento — verifique o valor ou atribua manualmente", "Русский (Russian)": "Платежа всё нет — проверьте сумму или назначьте вручную", "日本語 (Japanese)": "まだ支払いがありません — 金額を確認するか手動で割り当ててください", "中文 (Chinese)": "仍无付款 — 请检查金额或手动指定", "العربية (Arabic)": "لا توجد دفعة بعد — تحقق من المبلغ أو عيّنه يدويًا", "हिन्दी (Hindi)": "अभी भी भुगतान नहीं — राशि जाँचें या हाथ से असाइन करें" },
  "Assign to a transaction": { "Türkçe": "Bir işleme ata", "Deutsch": "Einem Umsatz zuordnen", "Français": "Affecter à une transaction", "Italiano": "Assegna a una transazione", "Español (Spanish)": "Asignar a una transacción", "Português": "Atribuir a uma transação", "Русский (Russian)": "Назначить операции", "日本語 (Japanese)": "取引に割り当て", "中文 (Chinese)": "指定到交易", "العربية (Arabic)": "تعيين إلى معاملة", "हिन्दी (Hindi)": "लेनदेन को असाइन करें" },
  "Remove": { "Türkçe": "Kaldır", "Deutsch": "Entfernen", "Français": "Supprimer", "Italiano": "Rimuovi", "Español (Spanish)": "Eliminar", "Português": "Remover", "Русский (Russian)": "Удалить", "日本語 (Japanese)": "削除", "中文 (Chinese)": "移除", "العربية (Arabic)": "إزالة", "हिन्दी (Hindi)": "हटाएँ" },
  "Match now": { "Türkçe": "Şimdi eşleştir", "Deutsch": "Jetzt zuordnen", "Français": "Associer maintenant", "Italiano": "Abbina ora", "Español (Spanish)": "Emparejar ahora", "Português": "Corresponder agora", "Русский (Russian)": "Сопоставить сейчас", "日本語 (Japanese)": "今すぐ照合", "中文 (Chinese)": "立即匹配", "العربية (Arabic)": "مطابقة الآن", "हिन्दी (Hindi)": "अभी मिलाएँ" },
  "Matching…": { "Türkçe": "Eşleştiriliyor…", "Deutsch": "Wird zugeordnet…", "Français": "Association…", "Italiano": "Abbinamento…", "Español (Spanish)": "Emparejando…", "Português": "A corresponder…", "Русский (Russian)": "Сопоставление…", "日本語 (Japanese)": "照合中…", "中文 (Chinese)": "匹配中…", "العربية (Arabic)": "جارٍ المطابقة…", "हिन्दी (Hindi)": "मिलान हो रहा है…" },
  "receipts attached.": { "Türkçe": "fiş eklendi.", "Deutsch": "Belege angehängt.", "Français": "reçus joints.", "Italiano": "ricevute allegate.", "Español (Spanish)": "recibos adjuntados.", "Português": "recibos anexados.", "Русский (Russian)": "чеков прикреплено.", "日本語 (Japanese)": "件の領収書を添付しました。", "中文 (Chinese)": "张收据已附加。", "العربية (Arabic)": "إيصالات مرفقة.", "हिन्दी (Hindi)": "रसीदें जोड़ी गईं।" },
  "No confident match yet — the payment may not have reached the bank.": { "Türkçe": "Henüz net eşleşme yok — ödeme bankaya düşmemiş olabilir.", "Deutsch": "Noch keine sichere Zuordnung — die Zahlung ist vielleicht noch nicht bei der Bank.", "Français": "Pas encore de correspondance sûre — le paiement n'a peut-être pas atteint la banque.", "Italiano": "Nessuna corrispondenza certa — il pagamento potrebbe non essere ancora in banca.", "Español (Spanish)": "Aún sin coincidencia clara — el pago quizá no ha llegado al banco.", "Português": "Ainda sem correspondência segura — o pagamento pode não ter chegado ao banco.", "Русский (Russian)": "Уверенного совпадения пока нет — платёж мог ещё не дойти до банка.", "日本語 (Japanese)": "まだ確実な一致はありません — 支払いが銀行に届いていない可能性があります。", "中文 (Chinese)": "尚无确定匹配 — 付款可能还未到达银行。", "العربية (Arabic)": "لا توجد مطابقة مؤكدة بعد — ربما لم تصل الدفعة إلى البنك.", "हिन्दी (Hindi)": "अभी कोई पक्का मेल नहीं — भुगतान बैंक तक नहीं पहुँचा होगा।" },
  "Reconnect needed": { "Türkçe": "Yeniden bağlanmalı", "Deutsch": "Neu verbinden nötig", "Français": "Reconnexion requise", "Italiano": "Riconnessione necessaria", "Español (Spanish)": "Reconexión necesaria", "Português": "Reconexão necessária", "Русский (Russian)": "Нужно переподключить", "日本語 (Japanese)": "再接続が必要", "中文 (Chinese)": "需要重新连接", "العربية (Arabic)": "يلزم إعادة الاتصال", "हिन्दी (Hindi)": "पुनः कनेक्ट आवश्यक" },
